// listedDebugOf returns the debug value the registry list carries for the
// device with the given rowid.
func listedDebugOf(t *testing.T, h http.Handler, id int64) bool {
	t.Helper()
	resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/devices", "", adminToken)
	dr := decodeDeviceList(t, resp)
	resp.Body.Close()
	for _, d := range dr.Devices {
		if d.DeviceID == strconv.FormatInt(id, 10) {
			return d.Debug
		}
	}
	t.Fatalf("device %d missing from the registry list (%+v)", id, dr.Devices)
	return false
}

// TestDeviceDebugFlipRoute pins the PUT /admin/devices/{id}/debug route
// (android-tv-app 3.1): 200 on a real device with the registry list reading
// the new state back, 404 on an unknown id, 400 on a malformed body or a
// non-integer id, and 403 for a non-admin bearer (the admin group's gate).
func TestDeviceDebugFlipRoute(t *testing.T) {
	st := openAPIStore(t)
	ident := identity.NewService(st, nil)
	devices := pairing.NewService(st, nil)
	token := mintPairedDevice(t, devices)
	id := deviceRowID(t, st, token)
	h := authChainRouter(t, st, ident)

	// Flip on → 200, and the registry reads true (the route's read-back law:
	// the list, never the write).
	flip := doRequest(t, h, http.MethodPut, deviceDebugPath(id), `{"debug":true}`, adminToken)
	flip.Body.Close()
	if flip.StatusCode != http.StatusOK {
		t.Fatalf("flip on = %d, want 200", flip.StatusCode)
	}
	if !listedDebugOf(t, h, id) {
		t.Fatalf("registry debug after flip on = false, want true")
	}

	// Flip off (the whole-replacement convention — the boolean IS the state).
	unflip := doRequest(t, h, http.MethodPut, deviceDebugPath(id), `{"debug":false}`, adminToken)
	unflip.Body.Close()
	if unflip.StatusCode != http.StatusOK {
		t.Fatalf("flip off = %d, want 200", unflip.StatusCode)
	}
	if listedDebugOf(t, h, id) {
		t.Fatalf("registry debug after flip off = true, want false")
	}

	// Unknown device id → 404, nothing written.
	miss := doRequest(t, h, http.MethodPut, deviceDebugPath(424242), `{"debug":true}`, adminToken)
	defer miss.Body.Close()
	if miss.StatusCode != http.StatusNotFound {
		t.Fatalf("unknown device flip = %d, want 404", miss.StatusCode)
	}
	if eb := decodeError(t, miss); eb.Error.Code != "not_found" {
		t.Fatalf("unknown device flip code = %q, want not_found", eb.Error.Code)
	}

	// Malformed body → 400 (validation-first, nothing written).
	bad := doRequest(t, h, http.MethodPut, deviceDebugPath(id), `{not json}`, adminToken)
	defer bad.Body.Close()
	if bad.StatusCode != http.StatusBadRequest {
		t.Fatalf("malformed body flip = %d, want 400", bad.StatusCode)
	}

	// Non-integer path id → 400 (the adminDeviceBind convention).
	nonInt := doRequest(t, h, http.MethodPut, "/api/v1/admin/devices/abc/debug", `{"debug":true}`, adminToken)
	defer nonInt.Body.Close()
	if nonInt.StatusCode != http.StatusBadRequest {
		t.Fatalf("non-integer id flip = %d, want 400", nonInt.StatusCode)
	}

	// The device's own bearer is RoleClient: the admin group refuses it.
	client := doRequest(t, h, http.MethodPut, deviceDebugPath(id), `{"debug":true}`, token)
	defer client.Body.Close()
	if client.StatusCode != http.StatusForbidden {
		t.Fatalf("device-bearer flip = %d, want 403 (admin group gate)", client.StatusCode)
	}
}

// TestDeviceDebugProfileField pins the device-kind profile answer's debug
// field (android-tv-app 3.1): carried on the device kind, tracking the flip,
// omitted while false (the additive law — existing answers unchanged), and
// absent from the admin and user kinds' answers entirely.
func TestDeviceDebugProfileField(t *testing.T) {
	st := openAPIStore(t)
	ident := identity.NewService(st, nil)
	devices := pairing.NewService(st, nil)
	token := mintPairedDevice(t, devices)
	id := deviceRowID(t, st, token)
	h := authChainRouter(t, st, ident)

	// Fresh device: kind=device, Debug false, and the FIELD ABSENT from the
	// raw body (omitempty — the pre-3.1 wire shape is byte-unchanged at the
	// default).
	prof := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", token)
	raw := responseBytes(t, prof)
	pr := decodeProfileRaw(t, raw)
	if pr.Kind != profileKindDevice || pr.Debug {
		t.Fatalf("fresh device profile = {kind %q, debug %v}, want {device, false}", pr.Kind, pr.Debug)
	}
	if strings.Contains(raw, `"debug"`) {
		t.Fatalf("fresh device profile body carries debug field: %s (want omitted at default)", raw)
	}

	// Flip on through the ROUTE → the device's next /profile answer carries
	// debug true (the spec's flip-then-read scenario, the client's gate).
	flip := doRequest(t, h, http.MethodPut, deviceDebugPath(id), `{"debug":true}`, adminToken)
	flip.Body.Close()
	if flip.StatusCode != http.StatusOK {
		t.Fatalf("flip = %d, want 200", flip.StatusCode)
	}
	prof2 := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", token)
	raw2 := responseBytes(t, prof2)
	pr2 := decodeProfileRaw(t, raw2)
	if pr2.Kind != profileKindDevice || !pr2.Debug {
		t.Fatalf("flipped device profile = {kind %q, debug %v}, want {device, true}", pr2.Kind, pr2.Debug)
	}
	if !strings.Contains(raw2, `"debug":true`) {
		t.Fatalf("flipped device profile body lacks \"debug\":true: %s", raw2)
	}

	// Flip off again → the field disappears (the omitempty posture holds
	// after a flip, not only at mint).
	unflip := doRequest(t, h, http.MethodPut, deviceDebugPath(id), `{"debug":false}`, adminToken)
	unflip.Body.Close()
	prof3 := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", token)
	raw3 := responseBytes(t, prof3)
	if strings.Contains(raw3, `"debug"`) {
		t.Fatalf("unflipped device profile body carries debug field: %s", raw3)
	}

	// The other kinds' answers stay untouched by the field: the env-admin
	// profile carries no debug key at all.
	adminProf := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", adminToken)
	adminRaw := responseBytes(t, adminProf)
	if strings.Contains(adminRaw, `"debug"`) {
		t.Fatalf("admin profile body carries debug field: %s (want field absent)", adminRaw)
	}
}

// TestDeviceDebugListField pins the device registry DTO's debug field
// (android-tv-app 3.1): ALWAYS present on the wire (no omitempty — the SPA
// toggle renders the state, absence would read as null), false for every
// fresh device, and true only for the flipped device.
func TestDeviceDebugListField(t *testing.T) {
	st := openAPIStore(t)
	ident := identity.NewService(st, nil)
	devices := pairing.NewService(st, nil)
	tokenA := mintPairedDevice(t, devices)
	tokenB := mintPairedDevice(t, devices)
	idA := deviceRowID(t, st, tokenA)
	idB := deviceRowID(t, st, tokenB)
	h := authChainRouter(t, st, ident)

	// Fresh registry: both devices carry the debug:false field — the raw
	// bodies contain it twice (field presence is the additive contract).
	list := doRequest(t, h, http.MethodGet, "/api/v1/admin/devices", "", adminToken)
	raw := responseBytes(t, list)
	if got := strings.Count(raw, `"debug":false`); got != 2 {
		t.Fatalf("fresh registry carries %d debug:false fields, want 2 (always present): %s", got, raw)
	}
	dr := decodeDeviceListRaw(t, raw)
	for _, d := range dr.Devices {
		if d.Debug {
			t.Fatalf("fresh device %s lists debug true, want false", d.DeviceID)
		}
	}

	// Flip device A through the ROUTE → the list reads true for A and false
	// for B (the flip is per-device, never a global gate).
	flip := doRequest(t, h, http.MethodPut, deviceDebugPath(idA), `{"debug":true}`, adminToken)
	flip.Body.Close()
	list2 := doRequest(t, h, http.MethodGet, "/api/v1/admin/devices", "", adminToken)
	raw2 := responseBytes(t, list2)
	if !strings.Contains(raw2, `"debug":true`) {
		t.Fatalf("flipped registry body lacks \"debug\":true: %s", raw2)
	}
	dr2 := decodeDeviceListRaw(t, raw2)
	debugByID := map[string]bool{}
	for _, d := range dr2.Devices {
		debugByID[d.DeviceID] = d.Debug
	}
	if !debugByID[strconv.FormatInt(idA, 10)] || debugByID[strconv.FormatInt(idB, 10)] {
		t.Fatalf("registry debug by device = %v, want only device %d true", debugByID, idA)
	}
}
